INSERT INTO frameworks (id,name,short_name,version,category,issuing_body,jurisdiction,effective_date,control_count,structure,description,url,adopted,coverage_pct) VALUES ('iso-42001','ISO/IEC 42001:2023','ISO 42001','2023','AI Management','ISO/IEC','International','2023-12-18',38,'9 governance areas in Annex A','AI Management System (AIMS) standard providing a structured approach for managing AI risks and opportunities.','https://www.iso.org/standard/81230.html',true,31);
